SELECT 
FROM ai_running_reports
WHERE member_id = #{memberId}
  AND report_type = #{reportType}
ORDER BY created_at DESC, id DESC
LIMIT 1

SELECT 
FROM ai_running_reports
WHERE member_id = #{memberId}
  AND report_type = #{reportType}
  AND input_snapshot_hash = #{inputSnapshotHash}
  AND status = 'COMPLETED'
ORDER BY created_at DESC, id DESC
LIMIT 1

SELECT 
FROM ai_running_reports
WHERE member_id = #{memberId}
  AND report_type = #{reportType}
  AND status = #{status}
ORDER BY created_at DESC, id DESC
